"""A small dict-based ECS with canonical JSON snapshots.

World layout:  {entity_id: {component_name: component_data_dict}}

Components
----------
Position  : {"x": int, "y": int}
Health    : {"hp": int, "max_hp": int}
Inventory : {"items": [entity_id, ...]}   # cross-references other entities

save(world) produces deterministic bytes:
  * JSON with sorted keys and fixed separators
  * entities remapped to a canonical dense id order (0..n-1) derived from
    entity *content*, so two worlds that are equal up to id assignment
    snapshot identically
load() reverses the mapping, validating every component type against the
registry and re-pointing Inventory item references at the new ids.
"""

from __future__ import annotations

import json

__all__ = [
    "UnknownComponentError",
    "DanglingReferenceError",
    "create_world",
    "spawn",
    "add_component",
    "get_component",
    "destroy",
    "save",
    "load",
]


class UnknownComponentError(ValueError):
    """Raised when a snapshot contains a component type not in the registry."""


class DanglingReferenceError(ValueError):
    """Raised when an Inventory references an entity id absent from the world."""


# --------------------------------------------------------------------------
# Component registry: name -> (required fields, field types)
# --------------------------------------------------------------------------
COMPONENT_REGISTRY: dict[str, dict] = {
    "Position": {
        "fields": {"x": int, "y": int},
    },
    "Health": {
        "fields": {"hp": int, "max_hp": int},
    },
    "Inventory": {
        "fields": {"items": list},
        # names of fields holding entity-id references that must be remapped
        "entity_refs": ("items",),
    },
}


# --------------------------------------------------------------------------
# Core ECS operations
# --------------------------------------------------------------------------
def create_world() -> dict:
    return {}


def spawn(world: dict, entity_id: int | None = None) -> int:
    """Add a bare entity. If entity_id is None, use the next free id."""
    if entity_id is None:
        entity_id = max(world, default=-1) + 1
    if entity_id in world:
        raise ValueError(f"entity {entity_id} already exists")
    world[entity_id] = {}
    return entity_id


def add_component(world: dict, entity_id: int, name: str, data: dict) -> None:
    if entity_id not in world:
        raise KeyError(f"unknown entity {entity_id}")
    if name not in COMPONENT_REGISTRY:
        raise UnknownComponentError(
            f"unknown component type {name!r}; "
            f"known types: {sorted(COMPONENT_REGISTRY)}"
        )
    world[entity_id][name] = data


def get_component(world: dict, entity_id: int, name: str) -> dict:
    return world[entity_id][name]


def destroy(world: dict, entity_id: int) -> None:
    world.pop(entity_id, None)


# --------------------------------------------------------------------------
# Snapshotting
# --------------------------------------------------------------------------
def _canonical_sort_key(item) -> tuple:
    """Order entities by their serialized content so the ordering does not
    depend on how ids were originally assigned; ties broken by id."""
    eid, components = item
    payload = json.dumps(components, sort_keys=True, separators=(",", ":"))
    return (payload, eid)


def save(world: dict) -> bytes:
    """Serialize *world* to canonical JSON bytes.

    Entity ids are remapped to a dense canonical order (0..n-1). Any entity
    id appearing inside a component's reference fields (e.g. Inventory items)
    is translated through the same mapping.
    """
    ordered = sorted(world.items(), key=_canonical_sort_key)
    remap = {old_id: new_id for new_id, (old_id, _) in enumerate(ordered)}

    out_entities = []
    for old_id, components in ordered:
        stored = {}
        for cname, cdata in components.items():
            spec = COMPONENT_REGISTRY.get(cname)
            if spec is None:
                raise UnknownComponentError(
                    f"unknown component type {cname!r} on entity {old_id}; "
                    f"known types: {sorted(COMPONENT_REGISTRY)}"
                )
            entry = dict(cdata)
            for field in spec.get("entity_refs", ()):
                refs = entry[field]
                missing = [r for r in refs if r not in remap]
                if missing:
                    raise DanglingReferenceError(
                        f"{cname}.{field} of entity {old_id} references "
                        f"missing entities: {missing}"
                    )
                entry[field] = [remap[r] for r in refs]
            stored[cname] = entry
        out_entities.append(stored)

    doc = {"format": "ecs-snapshot-v1", "entities": out_entities}
    return json.dumps(doc, sort_keys=True, separators=(",", ":")).encode("utf-8")


def load(data: bytes) -> dict:
    """Rebuild a world from bytes produced by :func:`save`.

    Ids are restored as the dense 0..n-1 order used in the snapshot, and all
    Inventory references are re-pointed accordingly.
    """
    try:
        doc = json.loads(data.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError(f"snapshot is not valid JSON: {exc}") from exc
    if not isinstance(doc, dict) or "entities" not in doc:
        raise ValueError("snapshot is malformed: missing 'entities'")

    world: dict = {}
    n = len(doc["entities"])
    for new_id, components in enumerate(doc["entities"]):
        if not isinstance(components, dict):
            raise ValueError(
                f"snapshot is malformed: entity {new_id} is not an object"
            )
        entity = spawn(world, new_id)
        for cname, cdata in components.items():
            spec = COMPONENT_REGISTRY.get(cname)
            if spec is None:
                raise UnknownComponentError(
                    f"cannot load snapshot: unknown component type {cname!r} "
                    f"on entity {new_id}; known types: "
                    f"{sorted(COMPONENT_REGISTRY)}"
                )
            if not isinstance(cdata, dict):
                raise ValueError(
                    f"snapshot is malformed: component {cname!r} of entity "
                    f"{new_id} is not an object"
                )
            for field, ftype in spec["fields"].items():
                if field not in cdata or not isinstance(cdata[field], ftype):
                    raise ValueError(
                        f"snapshot is malformed: component {cname!r} of "
                        f"entity {new_id} lacks a valid {field!r} field"
                    )
            entry = dict(cdata)
            for field in spec.get("entity_refs", ()):
                bad = [r for r in entry[field] if not isinstance(r, int)
                       or not 0 <= r < n]
                if bad:
                    raise DanglingReferenceError(
                        f"snapshot is malformed: {cname}.{field} of entity "
                        f"{new_id} has out-of-range references {bad}"
                    )
            world[entity][cname] = entry
    return world

